l = []
n = int(input())
for _ in range(2 * n):
	l.append(input())
stk = []
visited = [False] * n
f = True
ans = []
for i in reversed(l):
	if i[0] == '+':
		if len(stk) == 0:
			f = False
			break
		t = stk.pop()
		ans.append(t)
		if visited[t - 1]:
			f = False
			break
		visited[t - 1] = True
	else:
		t = int(i[2:])
		if visited[t - 1]:
			f = False
			break
		if len(stk) > 0 and stk[-1] < t:
			f = False
			break
		stk.append(t)
if len(stk) != 0:
	f = False
if f:
	print('YES')
	print(*reversed(ans))
else:
	print('NO')
